      out.appendChild(h('div',{class:'panel rf-reveal'},[h('span',{class:'lbl',text:'The sentence'}),h('div',{class:'row',style:'flex-wrap:nowrap;justify-content:center'},[zVi(c.xv,24),zPlay(c.xv)]),h('div',{class:'small muted',text:c.vi+' · '+c.en})]));
